    private static void run(Scene scene){
        Ram memory=new Ram();for(Seed s:scene.seeds())memory.seed(s.address(),s.value(),s.width());
        int[] cursor={0},tails={0},budgetCursor={0};
        UnsupportedOperationException callMarker=new UnsupportedOperationException("controlled opaque CALL unavailable");
        UnsupportedOperationException budgetMarker=new UnsupportedOperationException("controlled row budget exhausted");
        LoopBudget budget=(site,address)->{
            ok(budgetCursor[0]<scene.budget().size(),"no extra row-budget step");Budget expected=scene.budget().get(budgetCursor[0]++);
            eq(new Budget(site,address),expected,"actual row-loopheader and guard pointer");
            if(budgetCursor[0]>scene.rows())throw budgetMarker;
        };
        Calls lower=new Calls(){
            @Override public VolatileBits invoke(Call actual){
                ok(cursor[0]<scene.steps().size(),"no unexpected opaque CALL");Step step=scene.steps().get(cursor[0]++);
                eq(actual,step.call(),"all actual site/kind/target/SP/19V/10N fields");
                if(step.throwsMarker())throw callMarker;
                memory.callback(()->{
                    for(Seed mutation:step.mutations()){
                        if(mutation.width()==8)memory.writeQword(mutation.address(),mutation.value());
                        else if(mutation.width()==4)memory.writeDword(mutation.address(),(int)mutation.value());
                        else throw new AssertionError("unknown supplied mutation");
                    }
                    eq(memory.readQword(step.retSlot()),step.expectedRet(),"owned CALL return slot read after callback writes");return null;
                });
                return step.returned();
            }
            @Override public NormalReturn tail(Tail actual){
                eq(++tails[0],1,"one actual nested E900 TAIL");eq(actual,scene.tail(),"all actual TAIL fields");
                return memory.callback(()->{
                    long rip=memory.readQword(actual.entry().rspBits());
                    return new NormalReturn(scene.tailV(),rip,actual.entry().rspBits()+8L,actual.entry().nonvolatileBits());
                });
            }
            @Override public long readGsQword58(){throw new AssertionError("unexpected GS");}
        };
        Supplier<NormalReturn> execute=()->ErrorCellIndexedChain232.execute(scene.entry(),memory,lower,budget);
        if(scene.error()==null)eq(execute.get(),scene.expected(),"full actual NormalReturn including oldXCHG/rawV/freshN/RET");
        else if(scene.error().equals("sameBudget")||scene.error().equals("sameCallMarker")){
            try{execute.get();throw new AssertionError("opaque prefix swallowed or replayed");}
            catch(UnsupportedOperationException ex){ok(ex==(scene.error().equals("sameBudget")?budgetMarker:callMarker),"same opaque prefix marker");}
        }else{
            try{execute.get();throw new AssertionError("corrupt actual helper return accepted");}
            catch(IllegalStateException ex){eq(ex.getMessage(),scene.error(),"actual caller return guard");}
        }
        eq(cursor[0],scene.steps().size(),"exact opaque CALL count");eq(tails[0],scene.tail()==null?0:1,"exact TAIL count");
        eq(budgetCursor[0],scene.budget().size(),"exact row-prefix budget count");eq(memory.trace,scene.trace(),"complete ordered original/callback RAM including atomic effects");
        System.out.println("PASS "+scene.id());
    }
    private static void eq(Object a,Object b,String label){checks++;if(!Objects.equals(a,b))throw new AssertionError(label+" actual="+a+" expected="+b);}
    private static void eq(long a,long b,String label){checks++;if(a!=b)throw new AssertionError(label+" actual="+Long.toHexString(a)+" expected="+Long.toHexString(b));}
    private static void ok(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static String event(String who,String op,long a,long value){return who+":"+op+":"+Long.toUnsignedString(a,16)+":"+Long.toUnsignedString(value,16);}
    private static final class Ram implements AtomicIndexedMemory229{
        private final Map<Long,Byte> data=new HashMap<>();private final List<String> trace=new ArrayList<>();private String who="P";
        void seed(long a,long value,int width){for(int j=0;j<width;j++)data.put(a+j,(byte)(value>>>(8*j)));}
        long load(long a,int width){long value=0;for(int j=0;j<width;j++){Byte b=data.get(a+j);if(b==null)throw new AssertionError("unowned RAM "+Long.toHexString(a+j));value|=(long)Byte.toUnsignedInt(b)<<(8*j);}return value;}
        <T>T callback(Supplier<T> work){String old=who;who="C";try{return work.get();}finally{who=old;}}
        @Override public int readDword(long a){long x=load(a,4);trace.add(event(who,"R32",a,x));return(int)x;}
        @Override public long readQword(long a){long x=load(a,8);trace.add(event(who,"R64",a,x));return x;}
        @Override public void writeDword(long a,int x){seed(a,Integer.toUnsignedLong(x),4);trace.add(event(who,"W32",a,Integer.toUnsignedLong(x)));}
        @Override public void writeQword(long a,long x){seed(a,x,8);trace.add(event(who,"W64",a,x));}
        @Override public long exchangeQword(long a,long x){long old=load(a,8);seed(a,x,8);trace.add(event(who,"X64",a,x)+":"+Long.toUnsignedString(old,16));return old;}
        @Override public int readUnsignedByte(long a){throw new AssertionError("unexpected byte read");}
        @Override public void writeByte(long a,int x){throw new AssertionError("unexpected byte write");}
        @Override public int lockedXaddDword(long a,int x){throw new AssertionError("unexpected XADD");}
        @Override public Bits128 read128(long a){throw new AssertionError("unexpected memory128 read");}
        @Override public void write128(long a,Bits128 x){throw new AssertionError("unexpected memory128 write");}
    }
